head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50211";
scwin.validCode = null;
scwin.obj = undefined;
scwin.frameId = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.mode

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "img_10", attr: "src", fn: function () { return "/img/filing/body/pop_title_3" + String(((String((dma_pageContext.get("mode") ?? "")) === "create") ? "0" : "1")) + ".gif"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_60", fn: function(){ return ((dma_pageContext.get("mode") ?? "") === 'create'); } }, { id: "tr_62", fn: function(){ return ((dma_pageContext.get("mode") ?? "") === 'create'); } }, { id: "c_otherwise_66", fn: function(){ return (!(((dma_pageContext.get("mode") ?? "") === 'create'))); } }, { id: "if_editUseTpCd", fn: function(){ return (!(String(((dma_editMidclass.get("editUseTpCd") ?? (() => { throw new Error("unresolved:" + "editMidclass.editUseTpCd"); })())) === null ? '' : ((dma_editMidclass.get("editUseTpCd") ?? (() => { throw new Error("unresolved:" + "editMidclass.editUseTpCd"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Insert();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50211' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50211' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.validCode = "${param.mode == \"update\"}";
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50211.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_editClssCd_onkeyup
 * @description ipt_editClssCd 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_editClssCd_onkeyup = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.checkCode(selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50211.ipt_editClssCd_onkeyup' }); }
};

/**
 * @method
 * @name img_106_onclick
 * @description img_106 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_106_onclick = async function(e){
    try {
        await scwin.insert()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50211.img_106_onclick' }); }
};

/**
 * @method
 * @name img_107_onclick
 * @description img_107 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_107_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50211.img_107_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Insert
 * @description Insert 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Insert = async function () {
    const sbmOptions = {
        id: "tx_fn_Insert",
        method: "post",
        action: "/filing/editClass.do",
        ref: "dma_InsertReq",
        target: "dlt_editUseTpCds=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_CheckCode_xhr
 * @description Check Code xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_CheckCode_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_CheckCode_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_CheckCode_xhr", unresolved: "action:self_submit:tx_fn_CheckCode_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function () {
    if (!await scwin.validate()) {
        return;
    }
    if (!scwin.validCode) {
        await $c.win.alert("코드가 유효하지 않습니다.");
        return;
    }
    $c.util.getComponent('dma_InsertReq').set('method', "updateEditMidclass");
    scwin.form_editForm.action = "/filing/editClass.do";
    await scwin.tx_fn_Insert();
};

/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function () {
    if (String(($c.util.getComponent("ipt_editClssCd") || { getValue: function () { return ''; } }).getValue() || '').length !== 5) { await $c.win.alert("편집기중분류코드는 다섯자리수입니다."); ($c.util.getComponent("ipt_editClssCd") && $c.util.getComponent("ipt_editClssCd").setFocus ? $c.util.getComponent("ipt_editClssCd").setFocus() : ($c.util.getComponent("ipt_editClssCd") && $c.util.getComponent("ipt_editClssCd").focus ? $c.util.getComponent("ipt_editClssCd").focus() : void 0)); return false; }
    if (String(($c.util.getComponent("ipt_editClssNm") || { getValue: function () { return ''; } }).getValue() || '').replace(/\s/g, '') === '') { await $c.win.alert("편집기중분류명을 입력해 주세요."); ($c.util.getComponent("ipt_editClssNm") && $c.util.getComponent("ipt_editClssNm").setFocus ? $c.util.getComponent("ipt_editClssNm").setFocus() : ($c.util.getComponent("ipt_editClssNm") && $c.util.getComponent("ipt_editClssNm").focus ? $c.util.getComponent("ipt_editClssNm").focus() : void 0)); return false; }
    return true;
};

/**
 * @method
 * @name setValidCode
 * @description set Valid Code 처리
 * @param {*} _validCode _validCode
 * @returns {void}
 * @hidden N
 */
scwin.setValidCode = function (_validCode) {
    scwin.validCode = _validCode;
};

/**
 * @method
 * @name checkCode
 * @description check Code 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCode = async function (obj) {
    if (obj.value.length < 5) {
        return;
    }
    scwin.form_editForm.action = "/filing/editClass.do";
    $c.util.getComponent('dma_InsertReq').set('method', "processCheckCode");
    const existCode = (await scwin.tx_fn_CheckCode_xhr());
    if (existCode) {
        $c.util.getComponent('txt_checkMessage').setLabel("※ 중복");
        scwin.setValidCode(false);
    } else {
        $c.util.getComponent('txt_checkMessage').setLabel("");
        scwin.setValidCode(true);
    }
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
